380	
381	export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;
382	
383	export const SLUG_MIN_LENGTH = 2;
384	export const SLUG_MAX_LENGTH = 48;
385	
386	/** Slugs the router or marketing pages already claim. */
387	export const RESERVED_SLUGS: readonly string[] = [
388	  "admin",
389	  "api",
390	  "auth",
391	  "billing",
392	  "blog",
393	  "changelog",
394	  "dashboard",
395	  "docs",
396	  "help",
397	  "login",
398	  "logout",
399	  "new",
400	  "pricing",
401	  "register",
402	  "settings",
403	  "static",
404	  "support",
405	  "taskflow",
406	  "www",
