409	/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
410	export function slugify(input: string): string {
411	  return input
412	    .normalize("NFKD")
413	    .replace(/[\u0300-\u036f]/g, "")
414	    .toLowerCase()
415	    .replace(/[^a-z0-9]+/g, "-")
416	    .replace(/^-+|-+$/g, "")
417	    .slice(0, SLUG_MAX_LENGTH)
418	    .replace(/-+$/g, "");
419	}
420	
421	export function isValidSlug(value: string): boolean {
422	  return (
423	    value.length >= SLUG_MIN_LENGTH &&
424	    value.length <= SLUG_MAX_LENGTH &&
425	    SLUG_PATTERN.test(value)
426	  );
427	}
428	
429	export function isReservedSlug(value: string): boolean {
430	  return RESERVED_SLUGS.includes(value);
431	}
432	
433	export class InvalidSlugError extends Error {
434	  readonly code = "validation_failed" as const;
435	
436	  constructor(readonly value: string, readonly reason: string) {
437	    super(`Invalid slug "${value}": ${reason}`);
438	    this.name = "InvalidSlugError";
439	  }
440	}
441	
442	export function assertValidSlug(value: string): void {
443	  if (!isValidSlug(value)) {
444	    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
445	  }
446	  if (isReservedSlug(value)) {
447	    throw new InvalidSlugError(value, "is reserved");
448	  }
449	}
