467	/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
468	export function projectKeyFromName(name: string): string {
469	  const words = name.trim().split(/\s+/).filter(Boolean);
470	  const letters =
471	    words.length >= 2
472	      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
473	      : (words[0] ?? "task").slice(0, 3);
474	  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
475	}
