542	 */
543	export async function requireActorFor(orgId: OrgId): Promise<Actor> {
544	  const principal = await getSessionPrincipal();
545	  if (principal === null) throw new UnauthorizedError();
546	  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);
