737	/**
738	 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
739	 *
740	 * Must call (do not reimplement): getPlanLimits, isArchived
741	 */
742	import { getPlanLimits } from "@/config/plan-limits";
743	import { createLogger } from "@/lib/logger";
744	import { isArchived } from "@/lib/soft-delete";
745	import * as activityRepo from "@/server/repositories/activity-repository";
746	import * as issueRepo from "@/server/repositories/issue-repository";
747	import * as orgRepo from "@/server/repositories/organization-repository";
748	import * as searchRepo from "@/server/repositories/search-repository";
749	import * as usageRepo from "@/server/repositories/usage-repository";
750	import { toIsoTimestamp } from "@/types/common";
751	import { runJob } from "./types";
752	import type { JobResult } from "@/server/jobs/types";
753	
754	const ORG_BATCH = 25;
755	const PAGE_SIZE = 100;
756	const MS_PER_DAY = 24 * 60 * 60 * 1000;
757	
758	const logger = createLogger("cleanup-archived-job");
759	
760	/**
761	 * The retention sweep. Soft-deleted rows are kept for as long as the plan
762	 * promises and no longer: the cut-off comes from `retentionDays`, so an
763	 * enterprise tenant keeps years of history where a free one keeps a month.
764	 *
765	 * Only the search documents are actually dropped here — the issue rows stay,
766	 * because the audit log still points at them — while the audit rows past the
767	 * window are purged outright.
768	 */
769	export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
770	  return runJob("cleanup-archived", async (result) => {
771	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
772	
773	    for (const orgId of orgIds) {
774	      const org = await orgRepo.findOrgById(orgId);
775	      if (!org) continue;
776	
777	      const { retentionDays } = getPlanLimits(org.plan);
778	      const cutoff = toIsoTimestamp(
779	        new Date(now.getTime() - retentionDays * MS_PER_DAY),
780	      );
781	
782	      const archived = await issueRepo.listIssues({
783	        orgId,
784	        limit: PAGE_SIZE,
785	        cursor: null,
786	        includeArchived: true,
787	      });
788	
789	      for (const issue of archived.items) {
790	        if (!isArchived(issue)) continue;
791	        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;
792	
793	        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
794	        result.processed += 1;
795	      }
796	
797	      try {
798	        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
799	        result.processed += purged;
800	      } catch (error) {
801	        result.failed += 1;
802	        logger.error("activity purge failed", {
803	          orgId,
804	          reason: error instanceof Error ? error.message : String(error),
805	        });
806	      }
807	    }
808	  });
809	}
810	/**
811	 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
812	 *
813	 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
814	 */
815	import { isEnabled } from "@/lib/feature-flags";
816	import { createLogger } from "@/lib/logger";
817	import * as notificationRepo from "@/server/repositories/notification-repository";
818	import * as orgRepo from "@/server/repositories/organization-repository";
819	import * as usageRepo from "@/server/repositories/usage-repository";
820	import * as userRepo from "@/server/repositories/user-repository";
821	import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
822	import { sendEmail } from "@/server/services/email-service";
823	import { buildFlagContext } from "@/server/services/feature-flag-service";
824	import { toIsoTimestamp } from "@/types/common";
825	import { runJob } from "./types";
826	import type { JobResult } from "@/server/jobs/types";
827	import type { Organization } from "@/types/organization";
828	
829	const ORG_BATCH = 50;
830	const MS_PER_DAY = 24 * 60 * 60 * 1000;
831	
832	const logger = createLogger("digest-email-job");
833	
834	/**
835	 * One pass per scheduler tick. Each org is only processed during the UTC hour
836	 * it configured, so a tick that runs every few minutes still sends exactly one
837	 * digest per day per recipient.
838	 */
839	export async function runDigestEmailJob(now: Date): Promise<JobResult> {
840	  return runJob("digest-email", async (result) => {
841	    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);
842	
843	    for (const orgId of orgIds) {
844	      const org = await orgRepo.findOrgById(orgId);
845	      if (!org || !shouldRunForOrg(org, now)) continue;
846	
847	      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;
848	
849	      const windowEnd = toIsoTimestamp(now);
850	      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));
851	
852	      for (const recipientId of await listDigestRecipients(orgId)) {
853	        try {
854	          const bundle = await buildDigest(
855	            orgId,
856	            recipientId,
857	            windowStart,
858	            windowEnd,
859	          );
860	          if (!bundle) continue;
861	
862	          const recipient = await userRepo.findUserById(recipientId);
863	          if (!recipient) continue;
864	
865	          const rendered = await renderDigest(bundle, recipient);
866	          await sendEmail({ to: recipient.email, ...rendered });
867	
868	          // Once digested, these notifications are no longer "unread" — this
869	          // is what keeps a later run inside the same window from sending
870	          // the same digest twice.
871	          for (const entry of bundle.entries) {
872	            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
873	          }
874	
875	          result.processed += 1;
876	        } catch (error) {
877	          result.failed += 1;
878	          logger.error("digest failed", {
879	            orgId,
880	            recipientId,
881	            reason: error instanceof Error ? error.message : String(error),
882	          });
883	        }
884	      }
885	    }
886	  });
887	}
