/**
 * Maps thrown domain errors onto `AppErrorShape`.
 *
 * The service layer throws (`PermissionDeniedError`, `TenantScopeError`,
 * `FeatureDisabledError`, `AlreadyArchivedError`, `InvalidSlugError`,
 * `ZodError`); Server Actions and Route Handlers never propagate those to the
 * client. Everything funnels through `toAppError()` so one thrown class maps
 * to exactly one `ErrorCode` and one HTTP status, app-wide.
 */
import { FeatureDisabledError } from "@/lib/feature-flags";
import { PermissionDeniedError } from "@/lib/permissions";
import { InvalidSlugError } from "@/lib/slug";
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { TenantScopeError } from "@/lib/tenant";
import type { ActionResult, AppErrorShape, ErrorCode } from "@/types/api";
import { ZodError, type ZodIssue } from "zod";

export const HTTP_STATUS_BY_CODE: Readonly<Record<ErrorCode, number>> = {
  unauthorized: 401,
  forbidden: 403,
  not_found: 404,
  validation_failed: 422,
  conflict: 409,
  rate_limited: 429,
  plan_limit_exceeded: 402,
  tenant_scope_violation: 403,
  internal_error: 500,
};

/** True for the error classes this module knows how to translate faithfully. */
export function isDomainError(error: unknown): boolean {
  return (
    error instanceof PermissionDeniedError ||
    error instanceof TenantScopeError ||
    error instanceof FeatureDisabledError ||
    error instanceof AlreadyArchivedError ||
    error instanceof InvalidSlugError ||
    error instanceof ZodError
  );
}

/** Collapses a `ZodError` into the `field → messages` map forms consume. */
export function fieldErrorsFromZod(
  error: ZodError,
): Readonly<Record<string, readonly string[]>> {
  const fields: Record<string, string[]> = {};
  for (const issue of error.issues as readonly ZodIssue[]) {
    const key = issue.path.length === 0 ? "_root" : issue.path.join(".");
    (fields[key] ??= []).push(issue.message);
  }
  return fields;
}

export function toAppError(error: unknown): AppErrorShape {
  if (error instanceof ZodError) {
    return {
      code: "validation_failed",
      message: "Please correct the highlighted fields.",
      fieldErrors: fieldErrorsFromZod(error),
    };
  }

  if (error instanceof PermissionDeniedError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: {
        action: error.action,
        resourceKind: error.decision.resourceKind,
        reason: error.decision.reason,
      },
    };
  }

  if (error instanceof TenantScopeError) {
    return {
      code: "tenant_scope_violation",
      message: "That resource belongs to a different organization.",
      meta: { expectedOrgId: error.expectedOrgId, actualOrgId: error.actualOrgId },
    };
  }

  if (error instanceof FeatureDisabledError) {
    return {
      code: "forbidden",
      message: error.message,
      meta: { flag: error.flag },
    };
  }

  if (error instanceof AlreadyArchivedError) {
    return {
      code: "conflict",
      message: error.message,
      meta: { entity: error.entity, id: error.id },
    };
  }

  if (error instanceof InvalidSlugError) {
    return {
      code: "validation_failed",
      message: error.message,
      fieldErrors: { slug: [error.message] },
      meta: { value: error.value },
    };
  }

  return {
    code: "internal_error",
    message:
      error instanceof Error ? error.message : "Something went wrong. Try again.",
  };
}

/** The failure envelope a Server Action returns instead of throwing. */
export function toActionResult(error: unknown): ActionResult<never> {
  return {
    ok: false,
    error: toAppError(error),
    submittedAt: new Date().toISOString(),
  };
}
import type {
  EventHandler,
  TaskflowEventMap,
  TaskflowEventPayload,
  TaskflowEventType,
  Unsubscribe,
} from "@/types/event";

/**
 * In-process, typed publish/subscribe bus.
 *
 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
 * every reactive concern `subscribe()`s at module init (see
 * `src/server/services/event-registry.ts`). Handlers are isolated — one
 * throwing handler never fails the emit or the sibling handlers.
 */

type HandlerSet = Set<EventHandler<TaskflowEventType>>;

const handlers = new Map<TaskflowEventType, HandlerSet>();

const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();

/** Registers a handler for one event type. Call the return value to detach. */
export function subscribe<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const set = handlers.get(type) ?? new Set();
  set.add(handler as EventHandler<TaskflowEventType>);
  handlers.set(type, set);
  return () => {
    set.delete(handler as EventHandler<TaskflowEventType>);
  };
}

/** Registers a handler that detaches itself after the first delivery. */
export function subscribeOnce<K extends TaskflowEventType>(
  type: K,
  handler: EventHandler<K>,
): Unsubscribe {
  const off = subscribe(type, (payload) => {
    off();
    return handler(payload);
  });
  return off;
}

/**
 * Publishes an event to every subscriber. Resolves once all handlers settle;
 * rejected handlers are reported to the error sinks, never rethrown.
 */
export async function emit<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): Promise<void> {
  const set = handlers.get(type);
  if (!set || set.size === 0) return;

  const results = await Promise.allSettled(
    [...set].map(async (handler) => {
      await (handler as EventHandler<K>)(payload);
    }),
  );

  for (const result of results) {
    if (result.status === "rejected") {
      reportHandlerError(type, result.reason);
    }
  }
}

/** Fire-and-forget variant for call sites that must not await delivery. */
export function emitAndForget<K extends TaskflowEventType>(
  type: K,
  payload: TaskflowEventPayload<K>,
): void {
  void emit(type, payload).catch((error: unknown) => {
    reportHandlerError(type, error);
  });
}

export function onHandlerError(
  sink: (type: TaskflowEventType, error: unknown) => void,
): Unsubscribe {
  errorSinks.add(sink);
  return () => {
    errorSinks.delete(sink);
  };
}

function reportHandlerError(type: TaskflowEventType, error: unknown): void {
  for (const sink of errorSinks) {
    try {
      sink(type, error);
    } catch {
      // A failing error sink must never escalate.
    }
  }
}

/** Number of live subscribers for an event; used by tests and diagnostics. */
export function subscriberCount(type: TaskflowEventType): number {
  return handlers.get(type)?.size ?? 0;
}

/** Detaches every handler. Test-only — never call from application code. */
export function resetEventBus(): void {
  handlers.clear();
  errorSinks.clear();
}

export type { TaskflowEventMap, TaskflowEventType, Unsubscribe };
import type { ArchiveScope, IsoTimestamp, SoftDeletable } from "@/types/common";
import { toIsoTimestamp } from "@/types/common";

/**
 * Soft-delete conventions.
 *
 * Issues, projects and comments are never physically removed — they get an
 * `archived_at` timestamp. Repositories must express "live rows only" through
 * these helpers so the predicate stays in one place; a raw
 * `isNull(table.archivedAt)` sprinkled through the data layer is exactly the
 * drift this module prevents.
 */

export function isArchived(row: SoftDeletable): boolean {
  return row.archivedAt !== null;
}

export function isLive(row: SoftDeletable): boolean {
  return row.archivedAt === null;
}

/** Filters an in-memory collection according to an `ArchiveScope`. */
export function applyArchiveScope<T extends SoftDeletable>(
  rows: readonly T[],
  scope: ArchiveScope = {},
): readonly T[] {
  return scope.includeArchived === true ? rows : rows.filter(isLive);
}

/** True when the repository should add the `archived_at IS NULL` predicate. */
export function shouldFilterArchived(scope: ArchiveScope = {}): boolean {
  return scope.includeArchived !== true;
}

/** The column patch that archives a row. */
export function archivePatch(now: Date = new Date()): {
  archivedAt: IsoTimestamp;
  updatedAt: IsoTimestamp;
} {
  const stamp = toIsoTimestamp(now);
  return { archivedAt: stamp, updatedAt: stamp };
}

/** The column patch that restores an archived row. */
export function restorePatch(now: Date = new Date()): {
  archivedAt: null;
  updatedAt: IsoTimestamp;
} {
  return { archivedAt: null, updatedAt: toIsoTimestamp(now) };
}

export class AlreadyArchivedError extends Error {
  readonly code = "conflict" as const;

  constructor(readonly entity: string, readonly id: string) {
    super(`${entity} ${id} is already archived.`);
    this.name = "AlreadyArchivedError";
  }
}

/** Guard for archive actions, so double-archiving is a domain-level conflict. */
export function assertNotArchived(
  entity: string,
  id: string,
  row: SoftDeletable,
): void {
  if (isArchived(row)) {
    throw new AlreadyArchivedError(entity, id);
  }
}
import type { OrgId, TenantScoped } from "@/types/common";
import type { Actor } from "@/types/member";

/**
 * Multi-tenancy invariant helpers.
 *
 * Every repository query must be filtered by `org_id`, and every row that
 * crosses a service boundary must be re-checked against the actor's org. These
 * helpers are the only sanctioned way to express that — a hand-written
 * `if (row.orgId !== actor.orgId)` is a review failure.
 */

export class TenantScopeError extends Error {
  readonly code = "tenant_scope_violation" as const;

  constructor(
    readonly expectedOrgId: OrgId,
    readonly actualOrgId: OrgId,
  ) {
    super(
      `Tenant scope violation: expected org ${expectedOrgId}, got ${actualOrgId}`,
    );
    this.name = "TenantScopeError";
  }
}

/** Throws unless `orgId` belongs to the actor's organization. */
export function assertOrgScope(actor: Actor, orgId: OrgId): void {
  if (actor.orgId !== orgId) {
    throw new TenantScopeError(actor.orgId, orgId);
  }
}

/** Throws unless every supplied row belongs to the actor's organization. */
export function assertRowsInScope<T extends TenantScoped>(
  actor: Actor,
  rows: readonly T[],
): void {
  for (const row of rows) {
    assertOrgScope(actor, row.orgId);
  }
}

/** Non-throwing predicate, for filtering rather than failing. */
export function isInOrgScope(actor: Actor, row: TenantScoped): boolean {
  return row.orgId === actor.orgId;
}

/** Narrows a nullable row to one the actor may see; `null` otherwise. */
export function scopedOrNull<T extends TenantScoped>(
  actor: Actor,
  row: T | null | undefined,
): T | null {
  if (!row) return null;
  return row.orgId === actor.orgId ? row : null;
}

/**
 * Wraps an arbitrary filter object with the actor's `orgId`, so repositories
 * cannot forget it. Always spread the caller filter first.
 */
export function withOrgScope<T extends object>(
  actor: Actor,
  filter: T,
): T & { orgId: OrgId } {
  return { ...filter, orgId: actor.orgId };
}
/**
 * Slug generation and validation, shared by organization creation, project
 * creation and the "is this slug free?" checks in both the Zod schemas and the
 * repositories. One implementation so the client preview and the server
 * insertion can never disagree.
 */

export const SLUG_PATTERN = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export const SLUG_MIN_LENGTH = 2;
export const SLUG_MAX_LENGTH = 48;

/** Slugs the router or marketing pages already claim. */
export const RESERVED_SLUGS: readonly string[] = [
  "admin",
  "api",
  "auth",
  "billing",
  "blog",
  "changelog",
  "dashboard",
  "docs",
  "help",
  "login",
  "logout",
  "new",
  "pricing",
  "register",
  "settings",
  "static",
  "support",
  "taskflow",
  "www",
];

/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
export function slugify(input: string): string {
  return input
    .normalize("NFKD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, "-")
    .replace(/^-+|-+$/g, "")
    .slice(0, SLUG_MAX_LENGTH)
    .replace(/-+$/g, "");
}

export function isValidSlug(value: string): boolean {
  return (
    value.length >= SLUG_MIN_LENGTH &&
    value.length <= SLUG_MAX_LENGTH &&
    SLUG_PATTERN.test(value)
  );
}

export function isReservedSlug(value: string): boolean {
  return RESERVED_SLUGS.includes(value);
}

export class InvalidSlugError extends Error {
  readonly code = "validation_failed" as const;

  constructor(readonly value: string, readonly reason: string) {
    super(`Invalid slug "${value}": ${reason}`);
    this.name = "InvalidSlugError";
  }
}

export function assertValidSlug(value: string): void {
  if (!isValidSlug(value)) {
    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
  }
  if (isReservedSlug(value)) {
    throw new InvalidSlugError(value, "is reserved");
  }
}

/**
 * Derives a slug from `input` that collides with nothing in `taken`, by
 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
 */
export function uniqueSlug(input: string, taken: Iterable<string>): string {
  const base = slugify(input) || "item";
  const used = new Set(taken);
  if (!used.has(base) && !isReservedSlug(base)) return base;

  for (let suffix = 2; suffix < 1_000; suffix += 1) {
    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
  }
  throw new InvalidSlugError(base, "exhausted unique suffixes");
}

/** Project keys are the short uppercase prefix shown on issue numbers (TF-12). */
export function projectKeyFromName(name: string): string {
  const words = name.trim().split(/\s+/).filter(Boolean);
  const letters =
    words.length >= 2
      ? words.slice(0, 3).map((w) => w[0] ?? "").join("")
      : (words[0] ?? "task").slice(0, 3);
  return letters.toUpperCase().replace(/[^A-Z0-9]/g, "").slice(0, 4) || "TASK";
}
/**
 * Resolves the request's `Actor` for a given org slug, or throws
 * `unauthorized` / `forbidden`. Every Server Action starts here.
 *
 * The `Actor` is the only thing `can()` and `assertOrgScope()` accept, so
 * this module is the seam between "there is an HTTP request with a cookie"
 * and the rest of the app, which knows nothing about requests.
 */
import { getSessionPrincipal } from "@/lib/session";
import { assertOrgScope } from "@/lib/tenant";
import { findOrgById } from "@/server/repositories/organization-repository";
import { resolveActorForOrg } from "@/server/services/session-service";
import type { OrgId } from "@/types/common";
import type { Actor } from "@/types/member";

/** Thrown when there is no usable session; mapped to a 401 by `toAppError`. */
export class UnauthorizedError extends Error {
  readonly code = "unauthorized" as const;

  constructor(message = "Sign in to continue.") {
    super(message);
    this.name = "UnauthorizedError";
  }
}

/** Thrown when the session is valid but has no membership in the target org. */
export class NoMembershipError extends Error {
  readonly code = "forbidden" as const;

  constructor(readonly orgSlug: string) {
    super(`You are not a member of "${orgSlug}".`);
    this.name = "NoMembershipError";
  }
}

/** The `Actor` for `orgSlug`, or a throw. Use this in Server Actions. */
export async function getActor(orgSlug: string): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();

  const actor = await resolveActorForOrg(principal, orgSlug);
  if (actor === null) throw new NoMembershipError(orgSlug);

  return actor;
}

/** Non-throwing variant, for layouts that render a signed-out state. */
export async function tryGetActor(orgSlug: string): Promise<Actor | null> {
  try {
    return await getActor(orgSlug);
  } catch (error) {
    if (error instanceof UnauthorizedError || error instanceof NoMembershipError) {
      return null;
    }
    throw error;
  }
}

/**
 * The `Actor` for an org already identified by id — used by Route Handlers
 * that receive an `orgId` in the payload rather than a slug in the path. The
 * session's active org must match, which `assertOrgScope()` enforces.
 *
 * `resolveActorForOrg` keys off the org *slug*, so the id is translated here
 * with a single repository lookup rather than by widening that signature —
 * the slug is the only handle the session layer knows.
 */
export async function requireActorFor(orgId: OrgId): Promise<Actor> {
  const principal = await getSessionPrincipal();
  if (principal === null) throw new UnauthorizedError();
  if (principal.activeOrgId === null) throw new NoMembershipError(orgId);

  const org = await findOrgById(orgId);
  if (org === null) throw new NoMembershipError(orgId);

  const actor = await resolveActorForOrg(principal, org.slug);
  if (actor === null) throw new NoMembershipError(org.slug);

  assertOrgScope(actor, orgId);
  return actor;
}
/**
 * Session cookie access. In Next 16 `cookies()` is async — every function
 * here is async for that reason, and nothing outside this module touches the
 * cookie jar, so the cookie's name, flags and lifetime are stated once.
 */
import { cookies } from "next/headers";
import { SESSION_COOKIE_NAME } from "@/schemas/session";
import { resolveSession } from "@/server/services/session-service";
import type { IsoTimestamp } from "@/types/common";
import type { SessionPrincipal } from "@/types/member";
import { parseIso } from "./date";

export async function getSessionToken(): Promise<string | null> {
  const jar = await cookies();
  return jar.get(SESSION_COOKIE_NAME)?.value ?? null;
}

/**
 * The signed-in principal, or `null` when there is no cookie, the token is
 * unknown, or the session has expired. Callers that need a hard failure use
 * `getActor()` in `@/lib/actor` instead.
 */
export async function getSessionPrincipal(): Promise<SessionPrincipal | null> {
  const token = await getSessionToken();
  if (token === null) return null;

  const principal = await resolveSession(token);
  if (principal === null) return null;

  return parseIso(principal.expiresAt).getTime() > Date.now() ? principal : null;
}

export async function setSessionCookie(
  token: string,
  expiresAt: IsoTimestamp,
): Promise<void> {
  const jar = await cookies();
  jar.set(SESSION_COOKIE_NAME, token, {
    httpOnly: true,
    sameSite: "lax",
    secure: process.env.NODE_ENV === "production",
    path: "/",
    expires: parseIso(expiresAt),
  });
}

export async function clearSessionCookie(): Promise<void> {
  const jar = await cookies();
  jar.delete(SESSION_COOKIE_NAME);
}
/**
 * Private helpers shared by the service layer.
 *
 * Two jobs only: build the `PermissionResource` descriptors `can()` expects
 * from a loaded row, and stamp the `EventEnvelope` every domain event carries.
 * Neither re-implements a cross-cutting concern — they are adapters onto
 * `@/lib/permissions` and `@/lib/event-bus`.
 */
import { toIsoTimestamp } from "@/types/common";
import type { Comment } from "@/types/comment";
import type { OrgId, UserId } from "@/types/common";
import type { EventEnvelope } from "@/types/event";
import type { Issue } from "@/types/issue";
import type { Actor, Member } from "@/types/member";
import type { PermissionResource } from "@/types/permission";
import type { Project } from "@/types/project";
import type { WebhookId } from "@/types/common";

/** Raised when a scoped lookup finds nothing; mapped to `not_found` by callers. */
export class NotFoundError extends Error {
  readonly code = "not_found" as const;

  constructor(
    readonly entity: string,
    readonly id: string,
  ) {
    super(`${entity} ${id} was not found`);
    this.name = "NotFoundError";
  }
}

/** Unwraps a repository read, turning the `null` case into a domain error. */
export function requireFound<T>(
  value: T | null | undefined,
  entity: string,
  id: string,
): T {
  if (value === null || value === undefined) {
    throw new NotFoundError(entity, id);
  }
  return value;
}

export function orgResource(orgId: OrgId): PermissionResource {
  return { kind: "organization", orgId };
}

export function billingResource(orgId: OrgId): PermissionResource {
  return { kind: "billing", orgId };
}

export function activityResource(orgId: OrgId): PermissionResource {
  return { kind: "activity", orgId };
}

export function notificationResource(
  orgId: OrgId,
  recipientId: UserId,
): PermissionResource {
  return { kind: "notification", orgId, recipientId };
}

export function webhookResource(
  orgId: OrgId,
  webhookId: WebhookId | null,
): PermissionResource {
  return { kind: "webhook", orgId, webhookId };
}

export function memberResource(member: Member): PermissionResource {
  return {
    kind: "member",
    orgId: member.orgId,
    memberId: member.id,
    targetUserId: member.userId,
    targetRole: member.role,
  };
}

export function projectResource(project: Project): PermissionResource {
  return {
    kind: "project",
    orgId: project.orgId,
    projectId: project.id,
    visibility: project.visibility,
    leadId: project.leadId,
  };
}

export function issueResource(issue: Issue): PermissionResource {
  return {
    kind: "issue",
    orgId: issue.orgId,
    projectId: issue.projectId,
    issueId: issue.id,
    authorId: issue.authorId,
    assigneeId: issue.assigneeId,
  };
}

export function commentResource(comment: Comment): PermissionResource {
  return {
    kind: "comment",
    orgId: comment.orgId,
    commentId: comment.id,
    authorId: comment.authorId,
  };
}

/** The three fields the bus stamps on every payload. */
export function envelope(orgId: OrgId, actorId: UserId | null): EventEnvelope {
  return { orgId, actorId, occurredAt: toIsoTimestamp(new Date()) };
}

/** Same envelope, taken from an `Actor` rather than assembled by hand. */
export function actorEnvelope(actor: Actor): EventEnvelope {
  return envelope(actor.orgId, actor.userId);
}

/** Names the fields an update actually changed, for `issue.updated`. */
export function changedFields<T extends object>(
  before: T,
  after: T,
): readonly string[] {
  return Object.keys(after).filter(
    (key) =>
      JSON.stringify(before[key as keyof T]) !==
      JSON.stringify(after[key as keyof T]),
  );
}
/**
 * Permanently removes rows archived longer ago than the plan's `retentionDays`.
 *
 * Must call (do not reimplement): getPlanLimits, isArchived
 */
import { getPlanLimits } from "@/config/plan-limits";
import { createLogger } from "@/lib/logger";
import { isArchived } from "@/lib/soft-delete";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as issueRepo from "@/server/repositories/issue-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as searchRepo from "@/server/repositories/search-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";

const ORG_BATCH = 25;
const PAGE_SIZE = 100;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("cleanup-archived-job");

/**
 * The retention sweep. Soft-deleted rows are kept for as long as the plan
 * promises and no longer: the cut-off comes from `retentionDays`, so an
 * enterprise tenant keeps years of history where a free one keeps a month.
 *
 * Only the search documents are actually dropped here — the issue rows stay,
 * because the audit log still points at them — while the audit rows past the
 * window are purged outright.
 */
export async function runCleanupArchivedJob(now: Date): Promise<JobResult> {
  return runJob("cleanup-archived", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org) continue;

      const { retentionDays } = getPlanLimits(org.plan);
      const cutoff = toIsoTimestamp(
        new Date(now.getTime() - retentionDays * MS_PER_DAY),
      );

      const archived = await issueRepo.listIssues({
        orgId,
        limit: PAGE_SIZE,
        cursor: null,
        includeArchived: true,
      });

      for (const issue of archived.items) {
        if (!isArchived(issue)) continue;
        if (issue.archivedAt === null || issue.archivedAt > cutoff) continue;

        await searchRepo.deleteSearchDocument(orgId, "issue", issue.id);
        result.processed += 1;
      }

      try {
        const purged = await activityRepo.purgeActivityBefore(orgId, cutoff);
        result.processed += purged;
      } catch (error) {
        result.failed += 1;
        logger.error("activity purge failed", {
          orgId,
          reason: error instanceof Error ? error.message : String(error),
        });
      }
    }
  });
}
/**
 * Builds and 'sends' the daily digest for every subscriber of every org whose digest hour has arrived.
 *
 * Must call (do not reimplement): isEnabled, buildDigest, sendEmail
 */
import { isEnabled } from "@/lib/feature-flags";
import { createLogger } from "@/lib/logger";
import * as notificationRepo from "@/server/repositories/notification-repository";
import * as orgRepo from "@/server/repositories/organization-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as userRepo from "@/server/repositories/user-repository";
import { buildDigest, listDigestRecipients, renderDigest } from "@/server/services/digest-service";
import { sendEmail } from "@/server/services/email-service";
import { buildFlagContext } from "@/server/services/feature-flag-service";
import { toIsoTimestamp } from "@/types/common";
import { runJob } from "./types";
import type { JobResult } from "@/server/jobs/types";
import type { Organization } from "@/types/organization";

const ORG_BATCH = 50;
const MS_PER_DAY = 24 * 60 * 60 * 1000;

const logger = createLogger("digest-email-job");

/**
 * One pass per scheduler tick. Each org is only processed during the UTC hour
 * it configured, so a tick that runs every few minutes still sends exactly one
 * digest per day per recipient.
 */
export async function runDigestEmailJob(now: Date): Promise<JobResult> {
  return runJob("digest-email", async (result) => {
    const orgIds = await usageRepo.listOrgIdsForRollup(ORG_BATCH);

    for (const orgId of orgIds) {
      const org = await orgRepo.findOrgById(orgId);
      if (!org || !shouldRunForOrg(org, now)) continue;

      if (!isEnabled("digest_email", buildFlagContext(null, org))) continue;

      const windowEnd = toIsoTimestamp(now);
      const windowStart = toIsoTimestamp(new Date(now.getTime() - MS_PER_DAY));

      for (const recipientId of await listDigestRecipients(orgId)) {
        try {
          const bundle = await buildDigest(
            orgId,
            recipientId,
            windowStart,
            windowEnd,
          );
          if (!bundle) continue;

          const recipient = await userRepo.findUserById(recipientId);
          if (!recipient) continue;

          const rendered = await renderDigest(bundle, recipient);
          await sendEmail({ to: recipient.email, ...rendered });

          // Once digested, these notifications are no longer "unread" — this
          // is what keeps a later run inside the same window from sending
          // the same digest twice.
          for (const entry of bundle.entries) {
            await notificationRepo.markRead(orgId, entry.notificationId, windowEnd);
          }

          result.processed += 1;
        } catch (error) {
          result.failed += 1;
          logger.error("digest failed", {
            orgId,
            recipientId,
            reason: error instanceof Error ? error.message : String(error),
          });
        }
      }
    }
  });
}

/**
 * True during the org's configured digest hour. Exported because the schedule
 * decision is worth testing on its own, without a database.
 */
export function shouldRunForOrg(org: Organization, now: Date): boolean {
  if (org.archivedAt !== null) return false;
  return now.getUTCHours() === org.settings.digestHourUtc;
}
