131	/**
132	 * In-process, typed publish/subscribe bus.
133	 *
134	 * Taskflow keeps `IssueService`, `NotificationService`, `ActivityService`, the
135	 * search indexer and the webhook dispatcher decoupled: writers `emit()`, and
136	 * every reactive concern `subscribe()`s at module init (see
137	 * `src/server/services/event-registry.ts`). Handlers are isolated — one
138	 * throwing handler never fails the emit or the sibling handlers.
139	 */
140	
141	type HandlerSet = Set<EventHandler<TaskflowEventType>>;
142	
143	const handlers = new Map<TaskflowEventType, HandlerSet>();
144	
145	const errorSinks = new Set<(type: TaskflowEventType, error: unknown) => void>();
146	
147	/** Registers a handler for one event type. Call the return value to detach. */
148	export function subscribe<K extends TaskflowEventType>(
149	  type: K,
150	  handler: EventHandler<K>,
151	): Unsubscribe {
152	  const set = handlers.get(type) ?? new Set();
153	  set.add(handler as EventHandler<TaskflowEventType>);
154	  handlers.set(type, set);
155	  return () => {
156	    set.delete(handler as EventHandler<TaskflowEventType>);
157	  };
158	}
159	
160	/** Registers a handler that detaches itself after the first delivery. */
161	export function subscribeOnce<K extends TaskflowEventType>(
162	  type: K,
163	  handler: EventHandler<K>,
164	): Unsubscribe {
165	  const off = subscribe(type, (payload) => {
166	    off();
167	    return handler(payload);
168	  });
169	  return off;
170	}
