172	/**
173	 * Publishes an event to every subscriber. Resolves once all handlers settle;
174	 * rejected handlers are reported to the error sinks, never rethrown.
175	 */
176	export async function emit<K extends TaskflowEventType>(
177	  type: K,
178	  payload: TaskflowEventPayload<K>,
179	): Promise<void> {
180	  const set = handlers.get(type);
181	  if (!set || set.size === 0) return;
182	
183	  const results = await Promise.allSettled(
184	    [...set].map(async (handler) => {
185	      await (handler as EventHandler<K>)(payload);
186	    }),
187	  );
188	
189	  for (const result of results) {
190	    if (result.status === "rejected") {
191	      reportHandlerError(type, result.reason);
192	    }
193	  }
194	}
195	
196	/** Fire-and-forget variant for call sites that must not await delivery. */
197	export function emitAndForget<K extends TaskflowEventType>(
198	  type: K,
199	  payload: TaskflowEventPayload<K>,
200	): void {
201	  void emit(type, payload).catch((error: unknown) => {
202	    reportHandlerError(type, error);
203	  });
204	}
205	
206	export function onHandlerError(
207	  sink: (type: TaskflowEventType, error: unknown) => void,
208	): Unsubscribe {
209	  errorSinks.add(sink);
210	  return () => {
211	    errorSinks.delete(sink);
212	  };
213	}
214	
215	function reportHandlerError(type: TaskflowEventType, error: unknown): void {
216	  for (const sink of errorSinks) {
217	    try {
218	      sink(type, error);
219	    } catch {
220	      // A failing error sink must never escalate.
221	    }
222	  }
223	}
224	
225	/** Number of live subscribers for an event; used by tests and diagnostics. */
226	export function subscriberCount(type: TaskflowEventType): number {
227	  return handlers.get(type)?.size ?? 0;
228	}
229	
230	/** Detaches every handler. Test-only — never call from application code. */
231	export function resetEventBus(): void {
232	  handlers.clear();
233	  errorSinks.clear();
234	}
