409	/** Lowercases, strips diacritics and punctuation, collapses to `a-z0-9-`. */
410	export function slugify(input: string): string {
411	  return input
412	    .normalize("NFKD")
413	    .replace(/[\u0300-\u036f]/g, "")
414	    .toLowerCase()
415	    .replace(/[^a-z0-9]+/g, "-")
416	    .replace(/^-+|-+$/g, "")
417	    .slice(0, SLUG_MAX_LENGTH)
418	    .replace(/-+$/g, "");
419	}
