421	export function isValidSlug(value: string): boolean {
422	  return (
423	    value.length >= SLUG_MIN_LENGTH &&
424	    value.length <= SLUG_MAX_LENGTH &&
425	    SLUG_PATTERN.test(value)
426	  );
427	}
