443	  if (!isValidSlug(value)) {
444	    throw new InvalidSlugError(value, "must match ^[a-z0-9]+(-[a-z0-9]+)*$");
445	  }
446	  if (isReservedSlug(value)) {
447	    throw new InvalidSlugError(value, "is reserved");
