451	/**
452	 * Derives a slug from `input` that collides with nothing in `taken`, by
453	 * appending `-2`, `-3`, … Repositories pass their existing slug set in.
454	 */
455	export function uniqueSlug(input: string, taken: Iterable<string>): string {
456	  const base = slugify(input) || "item";
457	  const used = new Set(taken);
458	  if (!used.has(base) && !isReservedSlug(base)) return base;
459	
460	  for (let suffix = 2; suffix < 1_000; suffix += 1) {
461	    const candidate = `${base.slice(0, SLUG_MAX_LENGTH - 5)}-${suffix}`;
462	    if (!used.has(candidate) && !isReservedSlug(candidate)) return candidate;
463	  }
464	  throw new InvalidSlugError(base, "exhausted unique suffixes");
465	}
