512	/**
513	 * Collects one recipient's unread notifications inside the window. Returns
514	 * `null` — rather than an empty bundle — when the org's plan does not include
515	 * the digest, or when there is nothing to say: the caller treats `null` as
516	 * "send nothing", so a quiet day produces no mail at all.
517	 */
518	export async function buildDigest(
519	  orgId: OrgId,
520	  recipientId: UserId,
521	  windowStart: IsoTimestamp,
522	  windowEnd: IsoTimestamp,
523	): Promise<DigestBundle | null> {
524	  const org = await orgRepo.findOrgById(orgId);
525	  if (!org) return null;
526	
527	  if (!isEnabled("digest_email", buildFlagContext(null, org))) return null;
528	
529	  const unread = await notificationRepo.listUnreadSince(
530	    orgId,
531	    recipientId,
532	    windowStart,
533	  );
534	
535	  const entries: DigestEntry[] = unread
536	    .filter((notification) => notification.createdAt <= windowEnd)
537	    .map((notification) => ({
538	      notificationId: notification.id,
539	      kind: notification.kind,
540	      title: notification.title,
541	      href: notification.href,
542	      occurredAt: notification.createdAt,
543	    }))
544	    .slice(0, DIGEST_MAX_ENTRIES);
545	
546	  if (entries.length < MIN_ENTRIES) return null;
547	
548	  return { orgId, recipientId, entries, windowStart, windowEnd };
549	}
