652	/** Groups a feed page by calendar day, newest day first. */
653	export function groupByDay(
654	  events: readonly ActivityEvent[],
655	): readonly ActivityGroup[] {
656	  const byDay = new Map<string, ActivityEvent[]>();
657	
658	  for (const event of events) {
659	    const day = event.occurredAt.slice(0, 10);
660	    const bucket = byDay.get(day) ?? [];
661	    bucket.push(event);
662	    byDay.set(day, bucket);
663	  }
