import { afterAll, beforeAll, expect, it, vi } from "vitest";
vi.mock("@/lib/logger", async () => (await import("./server/_support/doubles/misc")).loggerModule);
import { AlreadyArchivedError } from "@/lib/soft-delete";
import { hashToken } from "@/lib/hash";
import * as invitationRepo from "@/server/repositories/invitation-repository";
import * as subscriptionRepo from "@/server/repositories/subscription-repository";
import * as webhookRepo from "@/server/repositories/webhook-repository";
import * as userRepo from "@/server/repositories/user-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as orgService from "@/server/services/organization-service";
import * as projectService from "@/server/services/project-service";
import * as invitationService from "@/server/services/invitation-service";
import { resolveActorForOrg, switchActiveOrg } from "@/server/services/session-service";
import { registerEventHandlers } from "@/server/services/event-registry";
import { runTrialExpiryJob, runWebhookDeliveryJob, runUsageRollupJob, runOverdueIssueJob, runSearchReindexJob, runDigestEmailJob, runCleanupArchivedJob } from "@/server/jobs";
import { createTenant, useTemporaryDatabase } from "./server/_support/fixtures";

let cleanup: () => void;
beforeAll(async () => { cleanup = await useTemporaryDatabase(); registerEventHandlers(); });
afterAll(() => cleanup());

it("closed workspace scenario", async () => {
  const t = await createTenant("closeme", "growth");
  const other = await createTenant("other", "growth");
  await usageRepo.recomputeUsage(t.org.id);
  await usageRepo.recomputeUsage(other.org.id);
  const ep = await webhookRepo.insertEndpoint({ orgId: t.org.id, url: "https://x.test/h", eventTypes: ["billing.plan_changed"] } as never, "s");
  const d = await webhookRepo.enqueueDelivery(t.org.id, ep.id, "billing.plan_changed", "{}");
  const invitee = await userRepo.insertUser({ email: "inv@x.test", name: "inv", passwordHash: "x" });
  await invitationRepo.insertInvitation(t.org.id, { orgId: t.org.id, email: "inv@x.test", role: "member", expiresInDays: 14 }, t.userIds.owner, hashToken("tok"));

  await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "wrong" })).rejects.toThrow(/confirmation/);
  expect((await orgService.resolveOrgBySlug("closeme"))?.archivedAt).toBeNull();

  const closed = await orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closeme" });
  expect(closed.archivedAt).not.toBeNull();
  await expect(orgService.deleteOrganization(t.actors.owner, { orgId: t.org.id, confirmSlug: "closeme" })).rejects.toBeInstanceOf(AlreadyArchivedError);

  expect(await orgService.listOrganizationsForUser(t.userIds.member)).toEqual([]);
  expect(await orgService.resolveOrgBySlug("closeme")).toBeNull();
  const principal = { userId: t.userIds.member, email: "m", activeOrgId: t.org.id, expiresAt: "2999-01-01T00:00:00.000Z" } as never;
  expect(await resolveActorForOrg(principal, "closeme")).toBeNull();
  await expect(switchActiveOrg(principal, { orgId: t.org.id } as never)).rejects.toThrow();
  await expect(projectService.listProjects(t.actors.member, { orgId: t.org.id, limit: 10, cursor: null } as never)).rejects.toThrow();
  await expect(invitationService.acceptInvitation(invitee.id, { token: "tok" })).rejects.toThrow();

  const sub = await subscriptionRepo.findSubscription(t.org.id);
  expect(sub?.status).toBe("canceled");

  const future = new Date(Date.now() + 30 * 86400000);
  console.log(await runTrialExpiryJob(future), await runWebhookDeliveryJob(new Date()), await runUsageRollupJob(new Date()), await runOverdueIssueJob(future), await runSearchReindexJob(t.org.id), await runDigestEmailJob(future), await runCleanupArchivedJob(future));
  expect((await subscriptionRepo.findSubscription(t.org.id))?.plan).toBe("growth");
  expect((await subscriptionRepo.findSubscription(other.org.id))?.plan).toBe("free");
  console.log(d.id, (await activityRepo.listActivity({ orgId: t.org.id, limit: 50, cursor: null } as never)).items.map(i => i.action));

  const again = await orgService.createOrganization(invitee.id, { name: "Close me", slug: "closeme", plan: "free" });
  expect(again.slug).toBe("closeme-2");
  expect((await orgService.listOrganizationsForUser(other.userIds.member)).length).toBe(1);
});
EOF
